import Fastify, { type FastifyError } from "fastify";

const app = Fastify({ logger: true });

app.setErrorHandler<FastifyError>((err, req, reply) => {
  const status = err.statusCode ?? 500;
  if (status >= 500) req.log.error(err);
  reply.status(status).type("application/problem+json").send({
    type: "https://api.example.com/errors/" + (err.code ?? "internal"),
    title: status >= 500 ? "Internal error" : err.message, // never leak internals
    status,
    requestId: req.id,
  });
});

app.post<{ Body: { slotId: string } }>("/bookings", {
  schema: { body: { type: "object", required: ["slotId"],
    properties: { slotId: { type: "string" } }, additionalProperties: false } },
}, async (req, reply) => {
  const booking = await createBooking(req.body.slotId); // returns null if the slot is taken
  if (!booking) {
    throw Object.assign(new Error("Slot already taken"), { statusCode: 409, code: "slot_taken" });
  }
  return reply.status(201).header("Location", `/bookings/${booking.id}`).send(booking);
});

