import DataLoader from "dataloader";
import { pool } from "./db";

type User = { id: string; name: string };

// Called once per HTTP request, never at module level
export function createContext() {
  return {
    userById: new DataLoader<string, User | null>(async (ids) => {
      const { rows } = await pool.query<User>(
        "SELECT id, name FROM users WHERE id = ANY($1)", [ids]);
      const byId = new Map(rows.map((u) => [u.id, u]));
      // Must return one result per key, in the same order as ids
      return ids.map((id) => byId.get(id) ?? null);
    }),
  };
}

export const resolvers = {
  Post: {
    author: (post: { authorId: string }, _args: unknown, ctx: ReturnType<typeof createContext>) =>
      ctx.userById.load(post.authorId),
  },
};

