// CREATE TABLE idempotency_keys (
//   account_id text, key text, request_hash text NOT NULL,
//   locked_at timestamptz, response jsonb,
//   PRIMARY KEY (account_id, key));

export async function createPayment(accountId: string, key: string, body: PaymentInput) {
  const hash = sha256(canonicalJson(body)); // stable key order

  // 1. Claim the key in one statement (no long transaction, no network call)
  const claim = await db.query(
    `INSERT INTO idempotency_keys (account_id, key, request_hash, locked_at)
     VALUES ($1, $2, $3, now())
     ON CONFLICT (account_id, key) DO UPDATE SET locked_at = now()
       WHERE idempotency_keys.response IS NULL
         AND idempotency_keys.request_hash = $3
         AND (idempotency_keys.locked_at IS NULL
              OR idempotency_keys.locked_at < now() - interval '60 seconds')
     RETURNING key`, [accountId, key, hash]);

  if (claim.rowCount === 0) {
    const { rows: [row] } = await db.query(
      "SELECT request_hash, response FROM idempotency_keys WHERE account_id = $1 AND key = $2",
      [accountId, key]);
    if (row.request_hash !== hash) throw new HttpError(422, "key_reused_with_different_body");
    if (row.response === null) throw new HttpError(409, "request_in_progress");
    return row.response; // replay the stored result, do nothing else
  }

  try {
    // 2. Provider call OUTSIDE any transaction, with a key derived from ours
    const charge = await provider.charge(body, { idempotencyKey: `pay-${accountId}-${key}` });
    // 3. Record the payment and the response atomically
    return await db.transaction(async (tx) => {
      const payment = await insertPayment(tx, body, charge.id);
      await tx.query(
        "UPDATE idempotency_keys SET response = $3, locked_at = NULL WHERE account_id = $1 AND key = $2",
        [accountId, key, payment]);
      return payment;
    });
  } catch (err) {
    // Release the lock so a retry can continue; the provider key keeps that retry safe
    await db.query("UPDATE idempotency_keys SET locked_at = NULL WHERE account_id = $1 AND key = $2",
      [accountId, key]);
    throw err;
  }
}

export async function pay(orderId: string, amount: number) {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await fetch("/api/payments", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Idempotency-Key": crypto.randomUUID(),
        },
        body: JSON.stringify({ orderId, amount }),
      });
    } catch {
      await new Promise((r) => setTimeout(r, 500 * attempt));
    }
  }
}

