type Cursor = { t: string; id: string };
const encode = (c: Cursor) => Buffer.from(JSON.stringify(c)).toString("base64url");

function decode(s: string): Cursor {
  try {
    const c = JSON.parse(Buffer.from(s, "base64url").toString());
    if (typeof c?.t === "string" && typeof c?.id === "string") return c;
  } catch {}
  throw new HttpError(400, "invalid_cursor"); // a bad cursor is the client's fault, not a 500
}

export async function listPosts(tenantId: string, after?: string, limit = 20) {
  const take = Math.min(Math.max(Math.trunc(limit) || 20, 1), 100); // server-side cap
  const c = after ? decode(after) : null;

  const { rows } = await pool.query(
    `SELECT id, title, created_at,
            created_at::text AS cursor_t   -- keeps microseconds; a JS Date would not
     FROM posts
     WHERE tenant_id = $1
       AND ($2::timestamptz IS NULL OR (created_at, id) < ($2::timestamptz, $3))
     ORDER BY created_at DESC, id DESC
     LIMIT $4`,
    [tenantId, c?.t ?? null, c?.id ?? null, take + 1]); // one extra row

  const hasMore = rows.length > take;
  const page = rows.slice(0, take);
  const last = page.at(-1);
  return {
    items: page.map(({ cursor_t, ...post }) => post),
    nextCursor: hasMore && last ? encode({ t: last.cursor_t, id: String(last.id) }) : null,
  };
}
