import Redis from "ioredis";
const redis = new Redis(process.env.REDIS_URL!);

// INCR and set the expiry in one atomic step
const SCRIPT = `
  local n = redis.call("INCR", KEYS[1])
  if n == 1 then redis.call("PEXPIRE", KEYS[1], ARGV[1]) end
  return { n, redis.call("PTTL", KEYS[1]) }`;

export async function limit(key: string, max: number, windowMs: number) {
  const bucket = Math.floor(Date.now() / windowMs);
  const [count, ttl] = (await redis.eval(
    SCRIPT, 1, `rl:${key}:${bucket}`, windowMs)) as [number, number];
  return { ok: count <= max, retryAfterSec: Math.ceil(ttl / 1000) };
}

