import Stripe from "stripe";
import { db } from "@/lib/db";
import { queue } from "@/lib/queue";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function POST(req: Request) {
  const raw = await req.text(); // raw body, not req.json()
  const sig = req.headers.get("stripe-signature") ?? "";

  let event: Stripe.Event;
  try {
    event = stripe.webhooks.constructEvent(raw, sig, process.env.STRIPE_WEBHOOK_SECRET!);
  } catch {
    return new Response("invalid signature", { status: 400 });
  }

  const { rowCount } = await db.query(
    "INSERT INTO webhook_events (id, type) VALUES ($1, $2) ON CONFLICT (id) DO NOTHING",
    [event.id, event.type]);
  if (rowCount === 0) return new Response("duplicate", { status: 200 });

  await queue.add("stripe-event", { eventId: event.id }, { jobId: event.id });
  return new Response("ok", { status: 200 });
}

