// app/api/mobile/home/route.ts
import { getSession } from "@/lib/session"; // reads the HttpOnly cookie

const get = (url: string, ms: number, token: string) =>
  fetch(url, {
    headers: { authorization: `Bearer ${token}` },
    signal: AbortSignal.timeout(ms),
  }).then((r) => {
    if (!r.ok) throw new Error(`${url} -> ${r.status}`);
    return r.json();
  });

export async function GET() {
  const s = await getSession();
  if (!s) return Response.json({ error: "unauthenticated" }, { status: 401 });

  const [user, orders, recs] = await Promise.allSettled([
    get(`${process.env.USERS_URL}/users/${s.userId}`, 500, s.accessToken),
    get(`${process.env.ORDERS_URL}/orders?user=${s.userId}&limit=3`, 500, s.accessToken),
    get(`${process.env.RECS_URL}/recs/${s.userId}`, 300, s.accessToken), // optional
  ]);

  if (user.status === "rejected") return Response.json({ error: "unavailable" }, { status: 503 });
  return Response.json({
    name: user.value.name,
    activeOrders: orders.status === "fulfilled" ? orders.value.items : null,
    recommendations: recs.status === "fulfilled" ? recs.value.items.slice(0, 6) : [],
  });
}

